{
  "definition_simple": "古代书籍流传下来的版本。",
  "definition_standard": "指古代文献、书籍、经籍等在流传过程中形成的各种刻本、抄本或印本。",
  "pos": "名词",
  "semantic_class": "concrete",
  "sentences": [
    {
      "tier": "T1",
      "text": "这本书有很好的传本。"
    },
    {
      "tier": "T1",
      "text": "图书馆收藏了这部古籍的珍贵传本。"
    },
    {
      "tier": "T2",
      "text": "学者们正在仔细比对这几个不同的传本。"
    },
    {
      "tier": "T2",
      "text": "这个传本的文字比其他版本更完整。"
    },
    {
      "tier": "T3",
      "text": "由于年代久远，这个传本已经出现了不少脱文和讹字。"
    },
    {
      "tier": "T3",
      "text": "我们必须追溯到最早的传本才能还原作品的原貌。"
    },
    {
      "tier": "T4",
      "text": "专家通过对该书各个传本的流变进行梳理，终于理清了其版本源流。"
    },
    {
      "tier": "T5",
      "text": "这篇文献虽经后人多次抄录，但核心内容依然保留在现存的几个主要传本之中。"
    },
    {
      "tier": "T5",
      "text": "版本学研究不仅关注孤本，更要对海量的传本进行系统性的普查与鉴别。"
    },
    {
      "tier": "T6",
      "text": "面对浩如烟海的历代传本，校勘者必须具备精湛的文献学素养方能去伪存真。"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "串本",
      "explanation": "声母由卷舌音ch变成翘舌音c，且声调由阳平(chuán)变为去声(chuàn)，属于常见的语音误读。"
    },
    {
      "word": "喘本",
      "explanation": "声母中ch不变，但声调由阳平(chuán)误读为上声(chuǎn)，导致词义完全无法对应。"
    },
    {
      "word": "传盆",
      "explanation": "韵母由前鼻音an(chuán)误发为后鼻音en(pén)，且声调发生偏移，属于典型的谐音混淆。"
    }
  ],
  "primary_collocate": "版本",
  "collocation_distractors": [
    {
      "word": "流传",
      "explanation": "流传是动词，而传本是名词，两者语法词性不同，无法直接作为定中结构组合。"
    },
    {
      "word": "底本",
      "explanation": "底本指校勘时所依据的原本，虽然与书籍版本有关，但语义上有别于流传下来的版本总体。"
    },
    {
      "word": "刻本",
      "explanation": "刻本指雕版印刷的版本，是一个并列层级的具体分类，不能直接修饰传本。"
    }
  ],
  "collocation_wrong_collocate": "传书",
  "cloze_distractors": [
    {
      "word": "副本",
      "explanation": "副本指正本以外的复本，不符合古代文献流传版本的专业术语搭配。"
    },
    {
      "word": "课本",
      "explanation": "课本指学校教学用的书籍，属于现代教育范畴，与古代文献的传本概念无关。"
    },
    {
      "word": "原本",
      "explanation": "原本指最初的稿本或原本，而传本强调的是流传下来的版本，两者在概念上有先后和范围的区别。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "他今天早上传本了一份文件给经理。",
      "reason": "传本在这里被错误地当作动词使用，意为传送文件，违背了其作为名词指代古籍版本的本义。"
    },
    {
      "sentence": "这家公司生产的传本质量非常好。",
      "reason": "传本专属於古代文献与书籍领域，不能用于现代工业产品或商业制造物的语境中。"
    },
    {
      "sentence": "我们需要把这个传本跑得更快一些。",
      "reason": "传本是无生命的书籍版本名词，无法搭配具有运动或速度属性的动词。"
    }
  ],
  "spot_incorrect": {
    "sentence": "这座图书馆收藏了许多珍贵的历史传本，为古文献研究提供了重要的资料。",
    "error_description": "句子本身无语法错误，但如果将'传本'误用为指代现代出版物则属于语境错误。",
    "corrected_version": "这座图书馆收藏了许多珍贵的历史文献传本，为古文字研究提供了重要的资料。"
  },
  "word_family_forms": [],
  "word_family_fake_forms": [
    "传本性",
    "化传本",
    "传本化"
  ],
  "syn_ant_candidates": [
    {
      "word": "抄本",
      "type": "synonym"
    },
    {
      "word": "刻本",
      "type": "synonym"
    },
    {
      "word": "印本",
      "type": "synonym"
    },
    {
      "word": "善本",
      "type": "synonym"
    }
  ],
  "particle_candidates": []
}
